\begin{Aufgabe}{Zahlensysteme}
Wandle die Dezimalzahl $45$ in eine Binärzahl um. Gib den Rechenweg an. \BE \BE

\LoesungKaro{$45 = 101101_2$}{6}

Wandle $1011\,0110_2$ in eine Hexadezimalzahl um. \BE \BE

\LoesungKaro{$B6_{16}$}{4}
\end{Aufgabe}

\begin{Aufgabe}{Zahlensysteme}
